// Verdant demo site — generated by Panda. This script is the only "source"
// Panda extracts from (see panda.config.ts `include`): every css()/pattern()/
// recipe() call below is a literal call, so `panda cssgen` can statically
// find it and emit exactly the CSS the pages use, nothing more.
import { writeFileSync, mkdirSync, readFileSync, readdirSync, statSync } from 'node:fs'
import { join } from 'node:path'

// A hand-rolled recursive copy: some mounted/virtual filesystems choke on
// Node's native cpSync fast paths (fcopyfile/clonefile), so this sticks to
// plain read/write, which works everywhere.
function copyDir(src, dest) {
  mkdirSync(dest, { recursive: true })
  for (const entry of readdirSync(src)) {
    const srcPath = join(src, entry)
    const destPath = join(dest, entry)
    if (statSync(srcPath).isDirectory()) {
      copyDir(srcPath, destPath)
    } else {
      writeFileSync(destPath, readFileSync(srcPath))
    }
  }
}
