const themeToggleJs = `(function () {
  var LIGHT = { "surface.100": "#faf8f3", "surface.200": "#ffffff", "border": "#93866c", "ink": "#1c1a15", "ink.muted": "#5b5548", "accent": "#2f6b4a", "accent.strong": "#234f38", "accent.ink": "#ffffff", "focusRing": "#a5670a", "positive": "#1f7a6c", "critical": "#c1440e" };
  var DARK = { "surface.100": "#15140f", "surface.200": "#1e1c15", "border": "#726b53", "ink": "#f1ede2", "ink.muted": "#b6ae9c", "accent": "#7fcfa3", "accent.strong": "#5fb98c", "accent.ink": "#10241a", "focusRing": "#e8a83e", "positive": "#5cc9b7", "critical": "#ff8f5e" };
  function varName(key) { return "--colors-" + key.replace(/\\./g, "-"); }
  function apply(map) {
    var root = document.documentElement;
    Object.keys(map).forEach(function (k) { root.style.setProperty(varName(k), map[k]); });
  }
  var btn = document.getElementById("theme-switch");
  if (!btn) return;
  // Reflect the OS-driven theme that's already on screen, so the switch
  // never lies about the current state before it's touched.
  var forcedDark = window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches;
  btn.setAttribute("aria-checked", String(forcedDark));
  btn.addEventListener("click", function () {
    forcedDark = !forcedDark;
    btn.setAttribute("aria-checked", String(forcedDark));
    apply(forcedDark ? DARK : LIGHT);
  });
})();
`

const swRegisterJs = `if ('serviceWorker' in navigator) {
  window.addEventListener('load', function () {
    navigator.serviceWorker.register('/sw.js');
  });
}
`

const swJs = `// Verdant — minimal offline shell. Cache the three pages and their assets
// on install; serve cache-first, fall back to network, fall back to the
// cached page for navigations when both fail.
var CACHE = 'verdant-v1';
var SHELL = ['/', '/index.html', '/components.html', '/404.html', '/styles.css', '/theme-toggle.js', '/favicon.svg', '/manifest.json'];
self.addEventListener('install', function (event) {
  event.waitUntil(caches.open(CACHE).then(function (cache) { return cache.addAll(SHELL); }));
  self.skipWaiting();
});
self.addEventListener('activate', function (event) {
  event.waitUntil(
    caches.keys().then(function (keys) {
      return Promise.all(keys.filter(function (k) { return k !== CACHE; }).map(function (k) { return caches.delete(k); }));
    })
  );
  self.clients.claim();
});
self.addEventListener('fetch', function (event) {
  if (event.request.method !== 'GET') return;
  event.respondWith(
    caches.match(event.request).then(function (cached) {
      return cached || fetch(event.request).catch(function () {
        if (event.request.mode === 'navigate') return caches.match('/index.html');
      });
    })
  );
});
`

// Light, safe HTML minification: collapse inter-tag whitespace only — never
// touches text content, so copy stays intact.
const minifyHtml = (html) => html.replace(/>\s+</g, '><').trim() + '\n'

